const http = require('http');
const crypto = require('crypto');
const { promisify } = require('util');

// Kubernetes health check and graceful shutdown handler
// for a session-management microservice

const sessions = new Map();
let isShuttingDown = false;
let activeConnections = new Set();
let drainTimeout = null;

// Maximum allowed request body size (bytes) to prevent memory exhaustion
const MAX_BODY_SIZE = 1024 * 10; // 10 KB

// Session token generation
function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

// Middleware: authentication check
function authenticate(req) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) return null;
  const token = authHeader.slice(7);
  return sessions.get(token) || null;
}

// Request handler
function handleRequest(req, res) {
  activeConnections.add(res);
  res.on('close', () => activeConnections.delete(res));

  if (req.url === '/healthz' && req.method === 'GET') {
    if (isShuttingDown) {
      res.writeHead(503, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'shutting_down' }));
    } else {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'healthy' }));
    }
    return;
  }

  if (req.url === '/readyz' && req.method === 'GET') {
    res.writeHead(isShuttingDown ? 503 : 200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ ready: !isShuttingDown }));
    return;
  }

  if (req.url === '/api/session' && req.method === 'POST') {
    let body = '';
    let aborted = false;
    req.on('data', chunk => {
      if (aborted) return;
      body += chunk;
      if (body.length > MAX_BODY_SIZE) {
        aborted = true;
        res.writeHead(413, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Payload too large' }));
        req.destroy();
      }
    });
    req.on('end', () => {
      if (aborted) return;
      try {
        const { username, password } = JSON.parse(body);
        if (!username || !password) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Missing credentials' }));
          return;
        }
        // Simulated auth check (in production, check against DB)
        if (password.length < 8) {
          res.writeHead(401, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Invalid credentials' }));
          return;
        }
        const token = generateToken();
        sessions.set(token, { username, createdAt: Date.now(), valid: true });
        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ token, expiresIn: 3600 }));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
    return;
  }

  if (req.url === '/api/session' && req.method === 'DELETE') {
    const session = authenticate(req);
    if (!session) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Unauthorized' }));
      return;
    }
    const token = req.headers['authorization'].slice(7);
    sessions.delete(token);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ message: 'Session invalidated' }));
    return;
  }

  if (req.url === '/api/protected' && req.method === 'GET') {
    const session = authenticate(req);
    if (!session) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Unauthorized' }));
      return;
    }
    if (!session.valid) {
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Session revoked' }));
      return;
    }
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ data: 'sensitive_payload', user: session.username }));
    return;
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found' }));
}

const server = http.createServer(handleRequest);

// Graceful shutdown sequence for Kubernetes SIGTERM
let shutdownInProgress = false;
function gracefulShutdown(signal) {
  if (shutdownInProgress) {
    // Ignore duplicate signals - maintain shutdown invariants
    console.log(`Duplicate ${signal} ignored, shutdown already in progress`);
    return;
  }
  shutdownInProgress = true;
  console.log(`Received ${signal}, starting graceful shutdown...`);
  isShuttingDown = true;

  // Immediately invalidate all sessions (security-first approach)
  for (const [key, session] of sessions) {
    session.valid = false;
  }

  // Phase 1: Stop accepting new connections
  server.close(() => {
    console.log('Server closed, cleaning up sessions...');
    clearTimeout(drainTimeout);
    // Phase 3: Final cleanup
    sessions.clear();
    process.exit(0);
  });

  // Phase 2: Force close remaining connections after drain period
  drainTimeout = setTimeout(() => {
    for (const conn of activeConnections) {
      conn.end();
    }
  }, 5000);
}

// Register signal handlers (single registration, idempotent)
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Session service listening on port ${PORT}`);
});

module.exports = { server, sessions, gracefulShutdown };
